// Generated from the Wikimedia Commons API (action=query&prop=imageinfo&iiprop=url|extmetadata).
// All images are freely licensed (CC0, public domain, CC BY or CC BY-SA); see each file page for full terms.
// Scripts/check_images.sh checks that every file here has a credit and every credit a file.

/// One bundled photo's credit. `id` is the file name in Resources/Images without its extension.
struct ImageCredit: Identifiable, Sendable {
    let id: String
    /// What the photo actually shows (shown on the Credits screen and in "Illustrative" tooltips).
    let subject: String
    /// The Commons file title.
    let title: String
    let author: String
    let license: String
    /// Reuse conditions: "none" (CC0 / public domain), or any of "attribution required", "share-alike",
    /// "personality rights may apply" (identifiable people), "trademarks visible" (product or company marks).
    let restrictions: String
    /// The Commons file page (source and full licence terms).
    let page: String

    /// A ready-to-use attribution line (TASL: title, author, source, licence).
    var attribution: String { "\"\(title)\" by \(author), \(license), via Wikimedia Commons (\(page))" }
}

